import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


class Model(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    """

    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return torch.matmul(A.T, B.T)


class ModelNew(nn.Module):
    """
    Optimized version of Model using custom CUDA operators.
    Replaces the matrix multiplication with a hand‑written CUDA kernel
    that computes C = (A.T) @ (B.T).
    """

    def __init__(self):
        super(ModelNew, self).__init__()

        # ---------- Naive matrix‑multiplication kernel ----------
        element_mm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* __restrict__ a,
                               const float* __restrict__ b,
                               float* __restrict__ c,
                               int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;   // row index in C
        int j = idx % N;   // column index in C

        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += a[k * M + i] * b[j * K + k];
        }
        c[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto device = A.device();
    int K_A = A.size(0);
    int M_A = A.size(1);
    int N_B = B.size(0);   // number of rows in B (i.e., columns after transpose)
    float* C_data = torch::empty(M_A * N_B, torch::kFloat, device=device);
    const int block_size = 256;
    const int num_blocks = (M_A * N_B + block_size - 1) / block_size;
    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, C_data.data_ptr<float()>, M_A, K_A, N_B);
    return C_data;
}
"""
        element_mm_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

        # Compile the inline CUDA code
        self.matmul_cuda = load_inline(
            name="matmul_cuda",
            cpp_sources=element_mm_cpp_source,
            cuda_sources=element_mm_source,
            functions=["matmul_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Compute C = (A.T) @ (B.T)
        return self.matmul_cuda(A.T, B.T)
